export const getVerifySessionUrl = () => {




  return `/v1/admin/sessions/verify`
}

/**
 * Checks a session on behalf of an application’s backend and answers with its claims (`sub`, `sid`, `auth_time`, `amr`, `sp`, …): the same shape an access token carries. A backend cannot verify the cookie of a `stateful` session offline, so it sends the cookie’s value here; `exp` says how long it may rely on the answer (one `accessTokenTtl` of the session’s profile) before asking again. A call counts as activity on the session. An access token of a `hybrid` session is accepted too (verified, then checked against the revoked-session list), for a backend that would rather not verify JWTs itself. A refresh token is never accepted. Unknown, revoked and expired sessions answer 401 with `session.invalid_token`, `session.revoked` or `session.expired`; a session of another environment is unknown.
 * @summary Verify a session for a backend
 */
export const verifySession = async (verifySessionRequest: VerifySessionRequest, options?: Parameters<typeof dashboardFetch>[1]): Promise<AccessTokenClaims> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return dashboardFetch<AccessTokenClaims>(getVerifySessionUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(verifySessionRequest)
  }
);}





